# -*- coding: utf-8 -*-
"""Conteudo textual dos papeis de trabalho. Classes: RP = Realizado com evidencia publica; PL = Planejado por falta de acesso; SD = Simulado para fins didaticos."""
def pts(R, M, C, SHA, comp):
    g = M["global_"]; pm = M["execucao"]; tr = M["trivial"]; mu = R["mus"]
    f = lambda x: f"{x:,.0f}".replace(",", ".")
    f2 = lambda x: f"{x:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    cmp = {r["tipo_erro_inserido"][:3]: r for r in C}
    P = []
    def add(**k): P.append(k)
